import { fraction, type FractionValue } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'
import { above, below, between, tableLatex } from './normal.ts'

/* ==========================================================================
   Banaketak · Batxilergoa 2 · Zientziak — diagnostic, guided practice,
   exercise bank and challenges, with the scope of unit 14 of Santillana
   and Anaya 2.º Bachillerato Ciencias and the style of the Basque
   university entrance exam (all the exercises and numbers are our own).
   Every closed answer is a single exact number. The normal ones use the
   four-decimal table of normal.ts: every z has exactly two decimals, the
   answer is the table value or a difference of table values, and the
   formulas print the very numbers the code computes (the tests recompute
   them from μ, σ and x, and compare each normal approximation with the
   exact binomial). The review stage is short; the four new stages carry
   most of the work.
   ========================================================================== */

/** Arabic writes the decimal point instead of the comma, so {,} becomes . there */
const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
/** Same formula everywhere, decimal point in Arabic */
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })
/** A decimal written with the comma, as an exact fraction */
const v = (text: string): FractionValue => {
    const [whole, decimals = ''] = text.split(',')
    const sign = whole.startsWith('-') ? -1 : 1
    return fraction(sign * Number(whole.replace('-', '') + decimals), 10 ** decimals.length)
}
const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)
/** A table probability (in ten-thousandths) as an exact answer, and as a percentage */
const table = (tenThousandths: number) => fraction(tenThousandths, 10_000)
const percentOf = (tenThousandths: number) => fraction(tenThousandths, 100)
/** P(Z ≤ z) and P(Z > z) from the table, for LaTeX */
const P = (z: number) => tableLatex(below(z))
const Q = (z: number) => tableLatex(above(z))
const T = (tenThousandths: number) => tableLatex(tenThousandths)
/** z in braces, so that Basque never reads «$z» as a case ending */
const Z = '{z}'

